class Solution {
public:
    int minimumVisitedCells(std::vector<std::vector<int>>& grid) {
        int m = grid.size(), n = grid[0].size();
        if (m == 1 && n == 1) return 1;
        using P = std::pair<int, int>;
        std::vector<std::priority_queue<P, std::vector<P>, std::greater<P>>> row_heaps(m);
        std::vector<std::priority_queue<P, std::vector<P>, std::greater<P>>> col_heaps(n);
        row_heaps[0].push({1, grid[0][0]});
        col_heaps[0].push({1, grid[0][0]});
        int ans = -1;
        for (int i = 0; i < m; ++i) {
            for (int j = 0; j < n; ++j) {
                if (i == 0 && j == 0) continue;
                while (!row_heaps[i].empty() && row_heaps[i].top().second < j) {
                    row_heaps[i].pop();
                }
                while (!col_heaps[j].empty() && col_heaps[j].top().second < i) {
                    col_heaps[j].pop();
                }
                int d = INT_MAX;
                if (!row_heaps[i].empty()) d = std::min(d, row_heaps[i].top().first + 1);
                if (!col_heaps[j].empty()) d = std::min(d, col_heaps[j].top().first + 1);
                if (i == m - 1 && j == n - 1 && d != INT_MAX) return d;
                if (d != INT_MAX && grid[i][j] > 0) {
                    row_heaps[i].push({d, j + grid[i][j]});
                    col_heaps[j].push({d, i + grid[i][j]});
                }
            }
        }
        return ans;
    }
};

class Solution {
    public int minimumVisitedCells(int[][] grid) {
        int m = grid.length, n = grid[0].length;
        if (m == 1 && n == 1) return 1;
        java.util.PriorityQueue<int[]>[] rowHeaps = new java.util.PriorityQueue[m];
        java.util.PriorityQueue<int[]>[] colHeaps = new java.util.PriorityQueue[n];
        for (int i = 0; i < m; i++) rowHeaps[i] = new java.util.PriorityQueue<>((a, b) -> Integer.compare(a[0], b[0]));
        for (int j = 0; j < n; j++) colHeaps[j] = new java.util.PriorityQueue<>((a, b) -> Integer.compare(a[0], b[0]));
        rowHeaps[0].offer(new int[]{1, grid[0][0]});
        colHeaps[0].offer(new int[]{1, grid[0][0]});
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (i == 0 && j == 0) continue;
                while (!rowHeaps[i].isEmpty() && rowHeaps[i].peek()[1] < j) rowHeaps[i].poll();
                while (!colHeaps[j].isEmpty() && colHeaps[j].peek()[1] < i) colHeaps[j].poll();
                int d = Integer.MAX_VALUE;
                if (!rowHeaps[i].isEmpty()) d = Math.min(d, rowHeaps[i].peek()[0] + 1);
                if (!colHeaps[j].isEmpty()) d = Math.min(d, colHeaps[j].peek()[0] + 1);
                if (i == m - 1 && j == n - 1 && d != Integer.MAX_VALUE) return d;
                if (d != Integer.MAX_VALUE && grid[i][j] > 0) {
                    rowHeaps[i].offer(new int[]{d, j + grid[i][j]});
                    colHeaps[j].offer(new int[]{d, i + grid[i][j]});
                }
            }
        }
        return -1;
    }
}

var minimumVisitedCells = function(grid) {
    const m = grid.length, n = grid[0].length;
    if (m === 1 && n === 1) return 1;
    // Simple min heap for pair [dist, max_reach]
    function createHeap() {
        const h = [];
        return {
            push: (val) => {
                h.push(val);
                let idx = h.length - 1;
                while (idx > 0) {
                    let p = (idx - 1) >> 1;
                    if (h[p][0] > h[idx][0]) {
                        let tmp = h[p]; h[p] = h[idx]; h[idx] = tmp;
                        idx = p;
                    } else break;
                }
            },
            pop: () => {
                const top = h[0];
                const end = h.pop();
                if (h.length > 0) {
                    h[0] = end;
                    let idx = 0;
                    while ((idx << 1) + 1 < h.length) {
                        let left = (idx << 1) + 1, right = left + 1;
                        let best = (right < h.length && h[right][0] < h[left][0]) ? right : left;
                        if (h[best][0] < h[idx][0]) {
                            let tmp = h[best]; h[best] = h[idx]; h[idx] = tmp;
                            idx = best;
                        } else break;
                    }
                }
                return top;
            },
            peek: () => h[0],
            size: () => h.length
        };
    }
    const rowHeaps = Array.from({ length: m }, createHeap);
    const colHeaps = Array.from({ length: n }, createHeap);
    rowHeaps[0].push([1, grid[0][0]]);
    colHeaps[0].push([1, grid[0][0]]);
    for (let i = 0; i < m; i++) {
        for (let j = 0; j < n; j++) {
            if (i === 0 && j === 0) continue;
            while (rowHeaps[i].size() > 0 && rowHeaps[i].peek()[1] < j) rowHeaps[i].pop();
            while (colHeaps[j].size() > 0 && colHeaps[j].peek()[1] < i) colHeaps[j].pop();
            let d = Infinity;
            if (rowHeaps[i].size() > 0) d = Math.min(d, rowHeaps[i].peek()[0] + 1);
            if (colHeaps[j].size() > 0) d = Math.min(d, colHeaps[j].peek()[0] + 1);
            if (i === m - 1 && j === n - 1 && d !== Infinity) return d;
            if (d !== Infinity && grid[i][j] > 0) {
                rowHeaps[i].push([d, j + grid[i][j]]);
                colHeaps[j].push([d, i + grid[i][j]]);
            }
        }
    }
    return -1;
};
